problem:
Problem description
- There is a production planning setting with a raw material set $$\mathcal{R}$$, a product set $$\mathcal{P}$$, an equipment set $$\mathcal{E}$$, and a planning horizon $$\mathcal{T}$$.
- Each product $$p \in \mathcal{P}$$ has a product-specific yield from raw material, a product-specific labor requirement, and a unit profit coefficient.
- Each product is compatible with a required equipment type, and production must be carried out on that compatible equipment.
- Each equipment type $$e \in \mathcal{E}$$ may have a finite processing capacity in each period $$t \in \mathcal{T}$$, or it may be effectively unlimited.
- The available raw material supply and available regular labor hours are limited in each period.
- The market can absorb all feasible output, so sales are not intended to be the limiting factor unless an explicit demand upper bound is provided in the input data.
- The planning goal is to choose production and sales decisions over the horizon so that total profit is maximized.
- Required business constraints:
  - Do not consume more raw material than is available in any period.
  - Do not use more regular labor hours than are available in any period.
  - Produce each product only on its compatible equipment type.
  - Do not exceed the processing capacity of any equipment type in any period.
  - If demand upper bounds are provided, do not sell more than those limits.
  - Keep all production, resource usage, and sales quantities nonnegative.
  - Ensure that raw material usage, labor usage, and output quantities are consistent with the product-specific conversion and processing requirements.
- A solution is represented by:
  - $$x_{p,t}$$: quantity of product $$p$$ produced in period $$t$$.
  - $$m_{p,t}$$: amount of raw material assigned to product $$p$$ in period $$t$$.
  - $$\ell_{p,t}$$: labor hours used for product $$p$$ in period $$t$$.
  - $$s_{p,t}$$: quantity of product $$p$$ sold in period $$t$$, if sales are modeled separately from production.
  - $$Z$$: total profit over the planning horizon.

Input Format
{
  "sets": {
    "products": "List of products indexed by $$p \in \mathcal{P}$$.",
    "equipment_types": "List of equipment types indexed by $$e \in \mathcal{E}$$.",
    "periods": "List of planning periods indexed by $$t \in \mathcal{T}$$.",
    "raw_materials": "List of raw materials indexed by $$r \in \mathcal{R}$$; for this problem, usually $$|\mathcal{R}| = 1$$."
  },
  "parameters": {
    "yield_per_unit_raw": "Array $$\alpha_p$$ giving output quantity of product $$p$$ per unit of raw material.",
    "labor_hours_per_unit_raw": "Array $$\beta_p$$ giving labor hours required per unit of raw material for product $$p$$.",
    "unit_profit": "Array $$\pi_p$$ giving profit per unit of product $$p$$ sold.",
    "raw_material_supply": "Vector $$S_t$$ giving available raw material in period $$t$$.",
    "labor_capacity": "Vector $$L_t$$ giving available regular labor hours in period $$t$$.",
    "equipment_capacity": "Matrix $$K_{e,t}$$ giving the maximum processing or output capacity of equipment $$e$$ in period $$t$$; use $$+\infty$$ if uncapped.",
    "compatible_equipment": "Mapping $$\eta_p$$ giving the required equipment type for product $$p$$.",
    "demand_upper_bound": "Optional matrix $$D_{p,t}$$ giving the maximum sales quantity of product $$p$$ in period $$t$$; use $$+\infty$$ when sales are unrestricted."
  },
  "decision_variables": {
    "production_quantity": "Matrix $$x_{p,t}$$ of size $$|\mathcal{P}| \\times |\mathcal{T}|$$.",
    "raw_material_allocation": "Matrix $$m_{p,t}$$ of size $$|\mathcal{P}| \\times |\mathcal{T}|$$.",
    "labor_usage": "Matrix $$\\ell_{p,t}$$ of size $$|\mathcal{P}| \\times |\mathcal{T}|$$.",
    "sales_quantity": "Optional matrix $$s_{p,t}$$ of size $$|\mathcal{P}| \\times |\mathcal{T}|$$ if sales are tracked separately."
  }
}

Output Format
{
  "objective_value": "Scalar $$Z$$ giving the maximum total profit.",
  "production_plan": {
    "shape": "Matrix $$x_{p,t}$$ with size $$|\mathcal{P}| \\times |\mathcal{T}|$$.",
    "meaning": "Planned production quantity for each product $$p$$ in each period $$t$$."
  },
  "resource_usage": {
    "raw_material": {
      "shape": "Matrix $$m_{p,t}$$ with size $$|\mathcal{P}| \\times |\mathcal{T}|$$.",
      "meaning": "Raw material assigned to each product $$p$$ in each period $$t$$."
    },
    "labor": {
      "shape": "Matrix $$\\ell_{p,t}$$ with size $$|\mathcal{P}| \\times |\mathcal{T}|$$.",
      "meaning": "Labor hours consumed by each product $$p$$ in each period $$t$$."
    }
  },
  "sales_plan": {
    "shape": "Optional matrix $$s_{p,t}$$ with size $$|\mathcal{P}| \\times |\mathcal{T}|$$.",
    "meaning": "Quantity sold of each product $$p$$ in each period $$t$$, if reported separately from production."
  }
}

